//! The engine's foreign-function surface.
//!
//! Everything exported here is a thin, allocation-light wrapper over the core crates.
//! Kotlin bindings are generated by UniFFI from these annotations; see
//! `android/README.md`. No astrology logic lives in this crate.

#![forbid(unsafe_code)]

use kshana_time::{Instant, Utc, NS_PER_SEC};

uniffi::setup_scaffolding!();

/// Engine version string, from the workspace version.
#[uniffi::export]
pub fn engine_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// An exact instant: TAI seconds since 1958-01-01 plus nanoseconds.
#[derive(Clone, Copy, Debug, uniffi::Record)]
pub struct ExactInstant {
    /// Whole TAI seconds since the TAI epoch.
    pub tai_seconds: i64,
    /// Nanoseconds within the second, 0–999 999 999.
    pub nanos: u32,
}

impl From<Instant> for ExactInstant {
    fn from(i: Instant) -> Self {
        let ns = i.tai_ns();
        Self {
            tai_seconds: ns.div_euclid(NS_PER_SEC) as i64,
            nanos: ns.rem_euclid(NS_PER_SEC) as u32,
        }
    }
}

impl From<ExactInstant> for Instant {
    fn from(e: ExactInstant) -> Self {
        Instant::from_tai_ns(e.tai_seconds as i128 * NS_PER_SEC + e.nanos as i128)
    }
}

/// Civil UTC fields.
#[derive(Clone, Copy, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct UtcFields {
    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub nanos: u32,
}

/// Errors crossing the FFI boundary.
#[derive(Debug, uniffi::Error)]
#[uniffi(flat_error)]
pub enum KshanaError {
    /// A civil date-time field was out of range.
    InvalidUtc(String),
    /// A house system is undefined for the given latitude.
    PolarLatitude,
    /// Not implemented yet.
    NotImplemented,
    /// Engine failure (kernel missing, instant out of range).
    Engine(String),
}

impl std::fmt::Display for KshanaError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            KshanaError::InvalidUtc(s) => write!(f, "invalid UTC: {s}"),
            KshanaError::PolarLatitude => write!(f, "house system undefined at this latitude"),
            KshanaError::NotImplemented => write!(f, "not implemented"),
            KshanaError::Engine(s) => write!(f, "engine: {s}"),
        }
    }
}

/// Exact instant from civil UTC (leap seconds honoured).
#[uniffi::export]
pub fn instant_from_utc(u: UtcFields) -> Result<ExactInstant, KshanaError> {
    let utc = Utc::new(u.year, u.month, u.day, u.hour, u.minute, u.second, u.nanos)
        .map_err(|e| KshanaError::InvalidUtc(format!("{e:?}")))?;
    let i = utc
        .to_instant()
        .map_err(|e| KshanaError::InvalidUtc(format!("{e:?}")))?;
    Ok(i.into())
}

/// Civil UTC from an exact instant.
#[uniffi::export]
pub fn utc_from_instant(i: ExactInstant) -> UtcFields {
    let u = Utc::from_instant(i.into());
    UtcFields {
        year: u.year,
        month: u.month,
        day: u.day,
        hour: u.hour,
        minute: u.minute,
        second: u.second,
        nanos: u.nanos,
    }
}

/// TT Julian Date of an instant as (jd1, jd2).
#[uniffi::export]
pub fn tt_julian_date(i: ExactInstant) -> Vec<f64> {
    let jd = Instant::from(i).tt_jd();
    vec![jd.jd1, jd.jd2]
}

/// Lahiri ayanamsa in degrees at an instant.
#[uniffi::export]
pub fn ayanamsa_lahiri(i: ExactInstant) -> f64 {
    let t = Instant::from(i).tt_centuries_since_j2000();
    kshana_vedic::ayanamsa_degrees(kshana_vedic::Ayanamsa::Lahiri, t)
}

/// Panchanga elements from tropical Sun and Moon longitudes at an instant.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct Panchanga {
    pub nakshatra: String,
    pub pada: u8,
    pub tithi_number: u8,
    pub tithi: String,
    pub is_shukla: bool,
    pub yoga: String,
    pub karana: String,
    pub moon_sidereal: f64,
    pub sun_sidereal: f64,
}

/// Compute the four angular panchanga limbs (vara is a date, left to the caller).
#[uniffi::export]
pub fn panchanga(moon_tropical: f64, sun_tropical: f64, i: ExactInstant) -> Panchanga {
    let ay = ayanamsa_lahiri(i);
    let moon = kshana_vedic::sidereal(moon_tropical, ay);
    let sun = kshana_vedic::sidereal(sun_tropical, ay);
    let n = kshana_vedic::nakshatra(moon);
    let t = kshana_vedic::tithi(moon, sun);
    let y = kshana_vedic::yoga(moon, sun);
    let k = kshana_vedic::karana(moon, sun);
    Panchanga {
        nakshatra: n.name().to_string(),
        pada: n.pada,
        tithi_number: t.number,
        tithi: t.name().to_string(),
        is_shukla: t.is_shukla(),
        yoga: y.name().to_string(),
        karana: k.name.to_string(),
        moon_sidereal: moon,
        sun_sidereal: sun,
    }
}

/// House systems exposed to the app.
#[derive(Clone, Copy, Debug, uniffi::Enum)]
#[allow(missing_docs)]
pub enum HouseSystem {
    WholeSign,
    Equal,
    Porphyry,
    Placidus,
}

/// Twelve cusps in degrees from local apparent sidereal time, true obliquity and
/// latitude (all radians).
#[uniffi::export]
pub fn house_cusps(
    system: HouseSystem,
    lst: f64,
    obliquity: f64,
    latitude: f64,
) -> Result<Vec<f64>, KshanaError> {
    let sys = match system {
        HouseSystem::WholeSign => kshana_houses::HouseSystem::WholeSign,
        HouseSystem::Equal => kshana_houses::HouseSystem::Equal,
        HouseSystem::Porphyry => kshana_houses::HouseSystem::Porphyry,
        HouseSystem::Placidus => kshana_houses::HouseSystem::Placidus,
    };
    kshana_houses::cusps(sys, lst, obliquity, latitude)
        .map(|c| c.to_vec())
        .map_err(|e| match e {
            kshana_houses::HouseError::PolarLatitude => KshanaError::PolarLatitude,
            _ => KshanaError::NotImplemented,
        })
}

